4	const MEETING_NOTE_TOOL_NAME = 'record_meeting_note_generation';
5	const RECONCILER_ACTOR = Object.freeze({
6	    authSource: 'internal',
7	    sub: 'eve_meeting_note_reconciler',
8	    person_id: 'internal_api'
9	});
